#pragma once
#include <stdint.h>

#include "Settings.h"
#include "nav/Nav.h"

// The vario's own sounds: the power-on sequence and the climb/sink tone.
//
// Power-on: a short climb beep at the vario volume (so the pilot can judge the level), a pause,
// then "Ready". The normal tone is held off until that has finished.
//
// In flight: beeps that rise in pitch and quicken with the climb rate, and a continuous low tone
// in strong sink, as set in the Vario settings. update() only works out what the tone should be;
// the sound itself is generated by the audio task (audio/Audio.cpp), so it keeps playing evenly
// even while the main loop is busy.
namespace variosound {

// What the tone generator should be doing.
struct ToneCommand {
  enum class Mode : uint8_t { Off, Climb, Sink };
  Mode mode;
  float hz;        // pitch; 0 when off
  uint16_t onMs;   // climb beeps: how long each beep lasts
  uint16_t offMs;  // climb beeps: the gap between beeps (0 and 0 = continuous tone, or silence)
};

// The tone for a vertical speed (nav.varioMs, m/s) under the given settings. Pure: it reads only its
// arguments, so it can be tested with exact values (tools/hil_test.py "vario_logic").
//   climb: a beeping tone when varioMs >= climbThreshold (the threshold itself counts), pitch =
//          base + rise x varioMs (200..2500 Hz), faster beeps for stronger lift (150..500 ms period);
//   sink:  a continuous tone when varioMs <= sinkThreshold (the threshold itself counts), pitch =
//          base / 2 + 20 x varioMs (150..1000 Hz), so it falls as the sink gets stronger;
//   off:   in between, muted, vario disabled, no barometer, or "only when flying" and not flying;
//          climb beeps / sink alarm can also be switched off separately.
ToneCommand toneFor(const NavState& nav, bool muted, const Settings& cfg);

// Call every few tens of milliseconds.
void update(uint32_t nowMs, const NavState& nav, bool muted);

#if PV_TEST
// How the power-on sequence went, measured on the vario itself so a test can read it from the status
// reply however long after the restart it first reaches the vario (the debug log only keeps the last
// few seconds).
struct BootInfo {
  bool done;           // "Ready" has been spoken
  float beepHz;        // pitch of the start-up beep
  uint32_t beepMs;     // how long the beep lasted
  uint32_t readyGapMs; // from the end of the beep to "Ready" being spoken
};
BootInfo bootInfo();
#endif

// Test build: forget what was last written to the debug log.
void resetLog();

}  // namespace variosound
